  "answer": 53,
  "format": "number",
  "dataset": "sales",
  "files": ["orders"],
  "pyVerify": "(lambda r: (r > r.quantile(0.75) + 1.5 * (r.quantile(0.75) - r.quantile(0.25))).sum())((lambda o: o['quantity'] * o['unit_price'] * (1 - o['discount_pct'] / 100))(data('sales', 'orders')))",
