  "answer": 386652,
  "format": "naira",
  "dataset": "process",
  "files": ["cases"],
  "verify": "SELECT ROUND(SUM(demurrage_ngn) * 1.0 / SUM(containers)) FROM cases WHERE checklist_pilot = 'No' AND docs_complete_on_arrival = 'No'",
